from pathlib import Path
import subprocess,tempfile,json,html
root=Path(__file__).resolve().parents[1]
with tempfile.TemporaryDirectory() as temp:
 out=Path(temp)
 (out/'package.json').write_text('{"type":"commonjs"}')
 subprocess.run(['node',str(root/'admin-web/node_modules/typescript/bin/tsc'),'--outDir',temp,'--rootDir',str(root),'--module','commonjs','--target','ES2022','--strict','--skipLibCheck',str(root/'shared/HomeService.ts'),str(root/'shared/MockRuntime.ts')],check=True)
 script="const {MockRuntime}=require(process.argv[1]);const {HomeService,demoHomeConfig}=require(process.argv[2]);(async()=>{const runtime=new MockRuntime();await runtime.auth.login({account:'student',password:'demo123'});const data=await new HomeService(runtime.contests,demoHomeConfig).load({keyword:'',category:null});process.stdout.write(JSON.stringify(data));})().catch(e=>{console.error(e);process.exit(1)});"
 data=json.loads(subprocess.check_output(['node','-e',script,str(out/'shared/MockRuntime.js'),str(out/'shared/HomeService.js')],text=True))
preview=root/'preview';preview.mkdir(exist_ok=True)
(preview/'home-data.json').write_text(json.dumps(data,ensure_ascii=False,indent=2))
e=html.escape
def date(v):return v[:10].replace('-','.')+(' '+v[11:16] if 'T' in v else '（原文仅日期）')
def status(v):return {'报名中':'#1FAA59','评审中':'#7C5CFC','公示中':'#18B7C2','已结束':'#5C6670','报名截止':'#E5484D'}.get(v,'#2C7BE5')
def card(x):return f'<article class="card"><div class="meta">{e(x["category"])} · {e(x["scopeType"])}<span style="color:{status(x["contestStatus"])}">{e(x["contestStatus"])}</span></div><h3>{e(x["name"])}</h3><strong>报名截止：{e(date(x["regEnd"]))}</strong><p>主办方：{e(x["organizationName"])}</p><p>参赛对象：{e(x["applicableScope"]["applicableNote"])}</p></article>'
urgent=''.join(f'<article class="urgent"><b>还有 {int(x["regEnd"][8:10])-10} 天截止</b><h3>{e(x["name"])}</h3><strong>报名截止：{e(date(x["regEnd"]))}</strong></article>' for x in data['urgent'])
